WITH transactions_by_account AS (SELECT account_id, SUM(amount) AS total_amount, COUNT(DISTINCT amount) AS unique_merchants FROM transactions WHERE merchant <> 'Shell' GROUP BY account_id) SELECT a.id, a.account_type, a.customer_id, tba.total_amount, tba.unique_merchants FROM accounts a LEFT OUTER JOIN transactions_by_account tba ON a.id = tba.account_id ORDER BY a.account_type ASC, total_amount DESC
